sp_widget.client_script:
api.controller = function() {
    var c = this;

    c.searchText = "";
    c.statusFilter = "";
    c.priorityFilter = "";

    c.clearFilters = function() {
        c.searchText = "";
        c.statusFilter = "";
        c.priorityFilter = "";
    };
};

sp_widget.css:
.hr-cases-page {
  padding: 25px;
  background: #f5f7fb;
  min-height: 100vh;
  font-family: Arial, sans-serif;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 22px;
}

.page-header h2 {
  margin: 0 0 6px;
  font-size: 26px;
  font-weight: 700;
  color: #172554;
}

.page-header p {
  margin: 0;
  color: #64748b;
  font-size: 14px;
}

.case-count {
  background: #ede9fe;
  color: #5b21b6;
  padding: 9px 16px;
  border-radius: 20px;
  font-weight: 600;
}

.filter-card {
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 20px;
  display: flex;
  gap: 12px;
  align-items: center;
}

.search-box {
  position: relative;
  flex: 1;
}

.search-box span {
  position: absolute;
  left: 12px;
  top: 9px;
}

.search-box input {
  padding-left: 38px;
}

.filter-card .form-control {
  height: 40px;
  border-radius: 8px;
  border: 1px solid #dbe2ea;
}

.filter-card select {
  width: 170px;
}

.btn-clear {
  height: 40px;
  padding: 0 18px;
  border: 1px solid #dbe2ea;
  background: white;
  border-radius: 8px;
  color: #475569;
  font-weight: 600;
}

.btn-clear:hover {
  background: #f8fafc;
}

.cases-card {
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0,0,0,.04);
}

.hr-table {
  margin-bottom: 0;
}

.hr-table thead {
  background: #f8fafc;
}

.hr-table th {
  padding: 14px 12px !important;
  border-bottom: 1px solid #e2e8f0 !important;
  color: #475569;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.hr-table td {
  padding: 14px 12px !important;
  vertical-align: middle !important;
  color: #334155;
  border-top: 1px solid #f1f5f9 !important;
}

.hr-table tbody tr:hover {
  background: #f8fafc;
}

.case-number {
  color: #3157d5;
  font-weight: 700;
  text-decoration: none;
}

.case-number:hover {
  text-decoration: underline;
}

.priority,
.status {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 15px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.priority-high {
  background: #fee2e2;
  color: #dc2626;
}

.priority-medium {
  background: #fef3c7;
  color: #d97706;
}

.priority-low {
  background: #dcfce7;
  color: #15803d;
}

.status-open {
  background: #e0f2fe;
  color: #0369a1;
}

.status-progress {
  background: #dbeafe;
  color: #2563eb;
}

.status-resolved {
  background: #dcfce7;
  color: #15803d;
}

.status-closed {
  background: #e2e8f0;
  color: #475569;
}

.empty-state {
  text-align: center;
  padding: 40px !important;
  color: #64748b;
}

@media (max-width: 900px) {
  .filter-card {
    flex-direction: column;
    align-items: stretch;
  }

  .filter-card select {
    width: 100%;
  }
}

sp_widget.script:
(function() {

    data.cases = [];

    var gr = new GlideRecord('x_snc_unified_hr_0_hr_case');
    gr.orderByDesc('sys_created_on');
    gr.query();

    while (gr.next()) {

        var caseObj = {};

        caseObj.sys_id = gr.getUniqueValue();
        caseObj.number = gr.getDisplayValue('number');
        caseObj.requested_by = gr.getDisplayValue('requested_by');
        caseObj.category = gr.getDisplayValue('category');
        caseObj.priority = gr.getDisplayValue('priority');
        caseObj.assignment_group = gr.getDisplayValue('assignment_group');
        caseObj.assigned_to = gr.getDisplayValue('assigned_to');
        caseObj.status = gr.getDisplayValue('status');
        caseObj.created = gr.getDisplayValue('sys_created_on');

        data.cases.push(caseObj);
    }

})();
